  expect(guestC.avatarFile && /avatars\/Avatar\d\d\.png/.test(guestC.avatarFile) && guestC.avatarLoaded === true,
    'GUEST: the avatar of the owner is inscribed in the circle and loaded (' + JSON.stringify({ f: guestC.avatarFile, w: guestC.avatarBox }) + ')');
  // ⚠️ WE MEASURE THE CONTRACT, AND NOT THE PIXELS OF THE BOX: in the full run the neighbouring sections
